using namespace std;

int main() {
    const __int128 MOD = 998244353;
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, L, R;
    cin >> n >> m >> L >> R;

    long long k = R - L + 1;

    if ((n * m) % 2 == 1) {
        __int128 exp = (__int128)n * m;
        __int128 base = (__int128)k;
        // Modular exponentiation
        __int128 result = 1;
        __int128 base_mod = base % MOD;
        __int128 e = exp;
        while (e > 0) {
            if (e & 1) result = (result * base_mod) % MOD;
            base_mod = (base_mod * base_mod) % MOD;
            e >>= 1;
        }
        cout << (long long)result << "\n";
    } else {
        long long e = R / 2 - (L - 1) / 2;
        long long o = k - e;
        __int128 E = e;
        __int128 O = o;
        __int128 exp = (__int128)n * m;

        // Function for modular exponentiation
        auto mod_pow = [](__int128 base, __int128 exp, __int128 mod) -> __int128 {
            __int128 result = 1;
            __int128 b = base % mod;
            __int128 e = exp;
            while (e > 0) {
                if (e & 1) result = (result * b) % mod;
                b = (b * b) % mod;
                e >>= 1;
            }
            return result;
        };

        __int128 a = mod_pow(E, exp, MOD);
        __int128 b = mod_pow(O, exp, MOD);
        __int128 sum = (a + b) % MOD;
        __int128 inv2 = (MOD + 1) / 2; // Modular inverse of 2 under MOD
        __int128 answer = (sum * inv2) % MOD;
        cout << (long long)answer << "\n";
    }

